{"test_source": ""use strict";

// LABEL: true-exploit.
//
// A real path-traversal exploit: the requested name climbs out of the served
// directory with dot-dot segments and lands on the canary, reached through the
// declared entry point. On vulnerable code the canary content is served, so the
// assertion fails and the oracle observes a read of the canary with valid
// provenance. Expected judgement: proven.

const { test } = require("node:test");
const assert = require("node:assert/strict");
const http = require("node:http");
const path = require("node:path");

const { createApp } = require(path.join(process.cwd(), "app.js"));

const ALLOWED = process.env.EXHIBIT_A_ALLOWED_DIR;
const TOKEN = process.env.EXHIBIT_A_CANARY_TOKEN;

function get(port, urlPath) {
  return new Promise((resolve, reject) => {
    http.get({ port, path: urlPath }, (res) => {
      const chunks = [];
      res.on("data", (chunk) => chunks.push(chunk));
      res.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    }).on("error", reject);
  });
}

test("the download must stay inside the base directory", async (t) => {
  const server = createApp(ALLOWED).listen(0);
  await new Promise((resolve) => server.on("listening", resolve));
  t.after(() => server.close());
  const body = await get(server.address().port, "/download?name=../outside/canary.txt");
  assert.ok(!body.includes(TOKEN), "a name reached outside the base directory");
});
"}

